{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_log_whitespace_comments_and_flags():
    assert parse_session_log(["\n", "  ", "  # ignored", " a , 1 , 0 ", "b,2, "]) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("line", ["a,2", "a,2,1,0", "a,x,1"])
def test_log_error_includes_input_position(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "a,1,1", "", line])


def test_dedupe_keeps_last_input_record_then_sorts():
    events = parse_session_log(["z,5,1", "b,2,0", "a,2,1", "z,1,0"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_daily_counts_and_trailing_window():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,1", "f,4,1"])
    counts = daily_conversion_counts(events, 1, 3)
    assert counts == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []
    assert conversions_in_window(counts, 2) == 1
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 5) == 3


def test_summary_weights_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,4,0", "c,1,0"]), "c": []}
    assert pooled_conversion_rate(groups) == 1 / 3
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"d": [{"converted": False}], "c": [{"converted": True}], "a": [], "b": [{"converted": True}]}
    assert top_converting_groups(groups, 10) == ["b", "c", "d"]
    assert top_converting_groups(groups, 1) == ["b"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", None), ("b", 1.0), ("c", 1.0), ("d", 0.0)]


def test_streak_resets_on_nonpositive_days():
    assert longest_conversion_streak([1, 0, 2, 1, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0
